/* Legacy surfaces use the same asset-version records and task ledger. */
(()=>{
const UI=EvalUI,C=EvaluationCore,core=()=>UI.core,AK=a=>C.key(a);
const button=(label,action,key='')=>`<button class="btn" data-v2="${action}" data-key="${esc(key)}">${label}</button>`;
function derived(obj,key,get){if(!obj)return;delete obj[key];Object.defineProperty(obj,key,{configurable:true,enumerable:false,get,set(){}});}
function latest(id){return core().list().filter(a=>a.id===id).at(-1);}
function flags(){
 for(const [obj,id] of [[S.import,'AS-IMPORT'],[S.human,'AS-HUMAN'],[S.regression,'AS-REG'],[S.suiteCandidate,'AS-SUITE-CANDIDATE'],[S.cal,'AS-CAL']]){derived(obj,'published',()=>latest(id)?.status==='已发布');derived(obj,'validated',()=>!!latest(id)?.validated);if(obj===S.cal)derived(obj,'approved',()=>latest(id)?.status==='已发布');}
 if(S.work){const a=()=>core().find(core().db.works[0]?.assetKey);derived(S.work,'published',()=>a()?.status==='已发布');derived(S.work,'validatedRev',()=>a()?.validated?S.work.revision:0);derived(S.work,'expertRev',()=>a()?.expertConfirmed?S.work.revision:0);derived(S.work,'stage',()=>core().db.works[0]?.status||'进行中');}
}
const originalSet=assetSet;
assetSet=function(){return originalSet().map(a=>core().adopt({...a,kind:a.kind==='adapter'?'executor':a.kind,governanceDomain:['dataset','case','reference'].includes(a.kind)?'开发':undefined,contentSet:a.kind==='dataset'?{member_kind:'sample',members:[]}:undefined,type:a.name,source:scene.file,owner:'林工',targets:[scene.key==='rag'?'非Agent应用':'Agent'],config:{scene:scene.key,actual:C.clone(a.content),references:a.kind==='suite'?a.content.references:[],lab:true},status:'草稿'}));};
function labFlags(){if(!L)return;derived(L,'confirmed',()=>{const a=assetSet();return a.length===11&&a.every(x=>x.expertConfirmed)?L.revision:0;});derived(L,'published',()=>{const a=assetSet();return a.length===11&&a.every(x=>x.status==='已发布')?L.revision:0;});}
function syncLab(recordNew=false){if(!L?.task)return;let t=S.evalTasks.find(t=>t.id===L.task.id);if(t?.labScenario&&t.labScenario!==scene.key){t=core().task({entry:'需求',labScenario:scene.key});L.task.id=t.id;}else if(!t){t=core().task({id:L.task.id,entry:'需求',labScenario:scene.key});}Object.assign(t,{name:L.task.name,goal:L.task.goal,object:L.task.object,objectVersion:L.task.version,type:scene.key==='rag'?'非Agent应用':'Agent',labScenario:scene.key,revision:L.revision,assemblyMode:'SUITE',contentMode:scene.key==='rag'?'DATASET':'CASE',executionScope:'DEMO_REPLAY_ONLY',objectProof:{kind:'fixture',ref:scene.key+'@'+scene.version}});t.deps=assetSet().map(a=>({key:a.key,kind:a.kind,label:a.type,required:true,assetId:a.id,assetVersion:a.version}));t.manifest=L.manifest?L.governanceManifest||null:null;for(const run of L.runs){let r=S.runs.find(r=>r.id===run.id);if(!r){if(recordNew)r=core().run(t,{id:run.id,template:scene.key});else{r={id:run.id,template:scene.key,legacyImported:true};S.runs.unshift(r);}}Object.assign(r,{taskId:t.id,build:run.manifest.object.version,verdict:run.summary.verdict,pass:run.summary.pass,fail:run.summary.fail,unknown:run.summary.unknown,trials:run.rows.length,attempts:run.rows.length,state:'已完成',snapshot:run.snapshots.length,v2Profile:scene.key,v2Rows:C.clone(run.rows),frozenManifest:{...C.clone(run.manifest),runtime:{scene:C.clone(scene),dataset:run.manifest.dataset,plan:run.manifest.plan,cases:run.manifest.cases,gate:run.manifest.suite}},v2Snapshots:run.snapshots.map((s,i)=>({id:'SNAP-'+(i+1),supersedes:i?'SNAP-'+i:null,verdict:s.summary.verdict,rows:C.clone(s.rows)}))});}UI.commit();}
pages.requirements=()=>pages.new().replace('新建评测任务','需求与对象');
const priorTask=pages.task;pages.task=()=>{const t=demandCurrent();if(t?.labScenario){if(L&&scene?.key===t.labScenario){S.evalTaskId=t.id;return labPage();}return head(t.name,t.id+' · '+t.objectVersion)+section('继续业务任务',`<div class="pad"><p>此任务保留原业务工作区、输入、资产和运行证据。</p><a class="btn primary" href="?uat=${encodeURIComponent(t.labScenario)}">打开任务工作区</a></div>`);}return priorTask();};
const priorLab=labAct;
labAct=function(action,el){
 const roles={pilot:'engineer',confirm:'expert',publish:'quality',freeze:'engineer',run:'engineer','supplement-save':scene?.key==='pet'?'ops':'engineer',rescore:'expert'};
 if(roles[action]&&!guard(roles[action]))return;
 if(action==='confirm'||action==='publish'){if(readiness().length||!L.pilot?.ready){toast('当前配置缺少有效试评，请返回试评步骤补齐。','error');return;}const list=assetSet();modal(action==='confirm'?'专家确认本次资产版本':'独立审核本次资产版本',`<p>每项使用同一审批记录，可在此处逐项处理。不会打包授予资格。</p>${table(['本次内容','版本 / 审批单','状态',''],list.map(a=>[esc(a.name),esc(a.version+' / '+a.governance.id),stateBadge(a.status),button('查看内容、变更和证据','asset',AK(a))]))}`,button('关闭','close'),true,true);return;}
 if(action==='freeze'||action==='run'){syncLab();const task=S.evalTasks.find(t=>t.id===L.task?.id);try{const check=core().preflight(task);if(check.gaps.length)throw Error(check.gaps.join('；'));if(action==='run'&&(!task.manifest||task.manifest.planDigest!==C.taskDigest(task)))throw Error('当前方案需要重新冻结');}catch(error){toast(error.message,'error');return;}}
 priorLab(action,el);labFlags();
 if(action==='freeze'&&!L.error&&L.manifest){const task=S.evalTasks.find(t=>t.id===L.task.id);L.governanceManifest=core().freezeTask(task,{scene:C.clone(scene),dataset:L.manifest.dataset,plan:L.manifest.plan,cases:L.manifest.cases,gate:L.manifest.suite,adapter:L.manifest.adapter});}
 if(action==='pilot'&&!L.error&&L.pilot?.ready){for(const a of assetSet()){if(a.status==='已发布')continue;core().validate(a,[{ok:true,detail:'业务结构与必填字段通过引擎检查'},{ok:true,detail:'实际数据、接口映射、用例与必测覆盖已检查'}]);core().evidence(a,{id:'LAB-VAL-'+a.id+'-'+a.version,demo:true,digest:C.digest(a),at:new Date().toISOString(),cases:L.pilot.rows,scope:'DEVELOPMENT_REPLAY_ONLY'});core().submit(a);}L.message='试评通过；已为本次资产版本生成统一审批待办。';}
 syncLab(action==='run'&&!L.error);UI.render();
};
const priorRender=render;render=function(){flags();labFlags();priorRender();document.body.classList.toggle('lab-mode',!!L&&(S.route==='lab'||S.route==='task'&&demandCurrent()?.labScenario===scene?.key));
 document.querySelectorAll('details').forEach(d=>{if(/修改本次被测输出/.test(d.querySelector('summary')?.textContent||'')){d.classList.add('v2-demo-box');}});
 for(const selector of ['#task-fixture','#task-observer','#comparison-mode','#reset-failure','#df-pilot-fixture','[data-action="reg-trigger"]'])document.querySelectorAll(selector).forEach(el=>{const box=el.closest('.field')||el;box.classList.add('v2-demo-box');if(!box.querySelector('.v2-demo-label'))box.insertAdjacentHTML('afterbegin','<span class="badge v2-demo-label">演示开关</span>');});
};
function legacyAsset(which){const id={human:'AS-HUMAN',reg:'AS-REG',suite:'AS-SUITE-CANDIDATE',cal:'AS-CAL'}[which],payload=which==='human'?{reviews:S.human.reviews,decisions:S.human.decisions,arbitration:S.human.arbitration}:which==='reg'?{run:S.regression.sourceRun,case:S.regression.sourceCase,checks:S.regression.checks}:which==='cal'?{revision:S.cal.revision,history:S.cal.history}:S.suiteCandidate;const version='v'+ScenarioEngine.fingerprint(payload);return core().adopt({id,version,kind:{human:'reference',reg:'case',suite:'suite',cal:'scorer'}[which],type:{human:'参考答案',reg:'评测用例',suite:'评测套件',cal:'评分器'}[which],name:{human:'独立人评参考',reg:'反馈回归用例',suite:'组合套件',cal:'裁判开发资格'}[which],source:'原流程记录 · '+id,targets:['Agent'],content:JSON.stringify(payload),assetSpec:{fields:{}},config:{processEvidence:payload}});}
document.addEventListener('click',e=>{
 const old=e.target.closest('[data-action]');if(!old)return;const action=old.dataset.action;
 if(/^(human-publish|reg-publish|suite-publish|cal-approve|cal-approve-confirm)$/.test(action)){e.stopImmediatePropagation();const a=legacyAsset(action.split('-')[0]);UI.checks(a);UI.commit();UI.assetDetail(a);return;}
 if(/^work-(submit|expert|validate|publish|publish-confirm|edit|edit-save)$/.test(action)){e.stopImmediatePropagation();UI.assetDetail(core().find(core().db.works[0].assetKey));}
},true);
flags();labFlags();syncLab();render();
})();
